select store_id, case when quantity >= 192 then 'high' when quantity >= 115 then 'mid' else 'low' end as quantity_bucket, product_id, round(stddev(quantity), 2) as stddev_quantity, count(quantity) as quantity_count, min(last_restock) as min_last_restock from inventory where last_restock between '2025-06-13' and '2025-10-01' and (last_restock <= '2025-08-01' or quantity <= 109) group by 1, 2, 3 having quantity_count < 1 order by stddev_quantity desc;
